static void copyBlend(const ConstImageView&source,const std::vector<float>&effect,ImageView output,float amount){for(int y=0;y<output.height;++y){auto*row=reinterpret_cast<float*>(reinterpret_cast<unsigned char*>(output.data)+std::ptrdiff_t(y)*output.row_bytes);for(int x=0;x<output.width;++x){auto index=(size_t(y)*output.width+x)*4;for(int c=0;c<3;++c){auto*srcRow=reinterpret_cast<const float*>(reinterpret_cast<const unsigned char*>(source.data)+std::ptrdiff_t(y)*source.row_bytes);float src=srcRow[x*4+c];row[x*4+c]=src+(effect[index+c]-src)*amount;}row[x*4+3]=reinterpret_cast<const float*>(reinterpret_cast<const unsigned char*>(source.data)+std::ptrdiff_t(y)*source.row_bytes)[x*4+3];}}}
