static OfxStatus entry(const char*action,const void*handle,OfxPropertySetHandle in,OfxPropertySetHandle out){try{auto effect=(OfxImageEffectHandle)handle;if(!std::strcmp(action,kOfxActionLoad)){fx=(const OfxImageEffectSuiteV1*)host->fetchSuite(host->host,kOfxImageEffectSuite,1);prop=(const OfxPropertySuiteV1*)host->fetchSuite(host->host,kOfxPropertySuite,1);param=(const OfxParameterSuiteV1*)host->fetchSuite(host->host,kOfxParameterSuite,1);return fx&&prop&&param?kOfxStatOK:kOfxStatErrMissingHostFeature;}if(!std::strcmp(action,kOfxActionUnload))return kOfxStatOK;if(!std::strcmp(action,kOfxActionDescribe))return describe(effect);if(!std::strcmp(action,kOfxImageEffectActionDescribeInContext))return context(effect);if(!std::strcmp(action,kOfxActionCreateInstance))return create(effect);if(!std::strcmp(action,kOfxActionDestroyInstance)){delete instance(effect);return kOfxStatOK;}if(!std::strcmp(action,kOfxActionInstanceChanged))return changed(effect,in);if(!std::strcmp(action,kOfxImageEffectActionRender))return render(effect,in);if(!std::strcmp(action,kOfxActionPurgeCaches)){clearFeedback(*instance(effect));return kOfxStatOK;}if(!std::strcmp(action,kOfxImageEffectActionGetFramesNeeded)){double time=0;check(prop->propGetDouble(in,kOfxPropTime,0,&time));double frames[]={time-1,time};check(prop->propSetDoubleN(out,"OfxImageClipPropFrameRange_Source",2,frames));return kOfxStatOK;}if(!std::strcmp(action,kOfxImageEffectActionGetClipPreferences)){text(out,"OfxImageClipPropComponents_Output",kOfxImageComponentRGBA);text(out,"OfxImageClipPropDepth_Output",kOfxBitDepthFloat);integer(out,kOfxImageEffectFrameVarying,1);return kOfxStatOK;}return kOfxStatReplyDefault;}catch(OfxStatus status){return status;}catch(const std::bad_alloc&){return kOfxStatErrMemory;}catch(...){return kOfxStatFailed;}}
